const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");

  if (idempotencyKey) {
    const existing = await db.query(
      "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
      [req.user.accountId, idempotencyKey]
    );
    if (existing.length) {
      return res.status(201).json(existing[0]);
    }
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const order = await db.query(
    "SELECT account_id FROM orders WHERE id = $1",
    [req.params.id]
  );
  if (!order.length || order[0].account_id !== req.user.accountId) {
    return res.status(403).end();
  }
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 RETURNING *",
    [req.params.id]
  );
  res.json(row);
});

module.exports = router;

turns.text:
If the connection drops mid-query, the `query()` call throws an error. The catch block then tries to ROLLBACK on a dead connection, which also throws—this second error masks the original one and propagates to the caller. The finally block still releases the broken connection.

So the caller sees the ROLLBACK failure, not what actually failed. Worse: if the connection dropped after COMMIT but before the return statement, the transaction was committed to the database but the client got an error and thinks it failed.

The fix is to wrap the ROLLBACK in its own try-catch so it doesn't mask the original error:

```javascript
async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // connection is dead, ignore
    }
    throw err;
  } finally {
    client.release();
  }
}
```

This preserves the original error and lets the caller know what actually went wrong.

app.js.text:
const express = require("express");
const { sessionUser } = require("./auth");
const accounts = require("./routes/accounts");
const orders = require("./routes/orders");

const idempotencyKeys = new Map();

const app = express();
app.use(express.json());

app.use((req, res, next) => {
  const start = Date.now();
  res.on("finish", () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Resolves the session cookie to a user row and sets req.user for every
// request; requests without a valid session are rejected here.
app.use(sessionUser);

app.use("/accounts", accounts);
app.use("/orders", (req, res, next) => {
  if (req.method === "POST" && req.headers["idempotency-key"]) {
    const key = `${req.user.accountId}:${req.headers["idempotency-key"]}`;
    if (idempotencyKeys.has(key)) {
      const cached = idempotencyKeys.get(key);
      return res.status(cached.status).json(cached.body);
    }
    const originalJson = res.json;
    res.json = function(data) {
      idempotencyKeys.set(key, { status: res.statusCode, body: data });
      return originalJson.call(this, data);
    };
  }
  next();
}, orders);

app.listen(process.env.PORT || 3000);

