    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    originalErr = err;
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Ignore rollback failures; throw the original error
    }
    throw originalErr;
  } finally {
    client.release();
  }
