const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers['idempotency-key'];

  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  // Check if we've already processed this request
  const existing = await db.query(
    "SELECT result FROM idempotency_keys WHERE account_id = $1 AND idempotency_key = $2 AND result IS NOT NULL",
    [req.user.accountId, idempotencyKey]
  );

  if (existing.length) {
    return res.status(201).json(JSON.parse(existing[0].result));
  }

  // Create the order
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  // Store the idempotency key and result
  await db.write(
    "INSERT INTO idempotency_keys (account_id, idempotency_key, result) VALUES ($1, $2, $3) ON CONFLICT (account_id, idempotency_key) DO UPDATE SET result = $3",
    [req.user.accountId, idempotencyKey, JSON.stringify(row)]
  );

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) {
    return res.status(404).end();
  }
  res.json(row);
});

module.exports = router;

turns.text:
The transaction starts with BEGIN. If the connection drops during the UPDATE or before COMMIT:

1. The query throws an error (connection lost).
2. The catch block tries to ROLLBACK, but the connection is dead, so ROLLBACK also throws.
3. That ROLLBACK error overwrites the original error and gets thrown to the caller.
4. The finally block releases the dead client back to the pool.

The problems: the original error is masked, and you don't know if it was the query or the rollback that failed. The server-side transaction is abandoned (eventually times out). The dead connection goes back into the pool and could be reused.

A better approach catches errors on the ROLLBACK itself so they don't mask the original error:

```javascript
async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Rollback failed, connection is likely dead. Don't mask the original error.
    }
    throw err;
  } finally {
    client.release();
  }
}
```

This preserves the original error and prevents the rollback failure from hiding what actually went wrong.

