const express = require("express");
const db = require("../db");

const router = express.Router();

const idempotencyCache = new Map();
const IDEMPOTENCY_TTL = 24 * 60 * 60 * 1000; // 24 hours

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (idempotencyKey) {
    const cacheKey = `${req.user.id}:${idempotencyKey}`;
    const cached = idempotencyCache.get(cacheKey);
    if (cached) return res.status(201).json(cached.row);
  }

  const account = await db.query(
    "SELECT id FROM accounts WHERE id = $1 AND deleted_at IS NULL",
    [req.user.accountId]
  );
  if (!account.length) return res.status(403).end();
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  if (idempotencyKey) {
    const cacheKey = `${req.user.id}:${idempotencyKey}`;
    idempotencyCache.set(cacheKey, { row, timestamp: Date.now() });
    setTimeout(() => idempotencyCache.delete(cacheKey), IDEMPOTENCY_TTL);
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(403).end();
  res.json(row);
});

module.exports = router;

