const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];

  if (idempotencyKey && idempotencyCache.has(idempotencyKey)) {
    return res.status(201).json(idempotencyCache.get(idempotencyKey));
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  if (idempotencyKey) {
    idempotencyCache.set(idempotencyKey, row);
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) {
    return res.status(404).end();
  }
  res.json(row);
});

module.exports = router;

turns.text:
If the connection drops mid-write, the error handling breaks down. Here's the sequence:

1. Say the connection dies during the main `query()` call. That query throws an error.

2. The catch block tries to run `ROLLBACK` on the dead connection. This also fails—you can't send commands over a closed connection.

3. If `ROLLBACK` throws, that new error overwrites the original one and gets thrown instead. You've lost the information about what actually went wrong.

4. The finally block tries `client.release()` on an already-dead client, which might fail silently or throw again depending on the driver.

The core issue: the code assumes the connection is still alive in the catch block. If the connection itself failed, attempting `ROLLBACK` is futile and creates a secondary error that masks the root cause.

A safer approach wraps the rollback:
```javascript
} catch (err) {
  try {
    await client.query("ROLLBACK");
  } catch (rollbackErr) {
    // connection is dead; can't rollback
  }
  throw err;
}
```

This preserves the original error and doesn't let a failed rollback hide it.

