const cache = new Map();

function getCacheKey(accountId, idempotencyKey) {
  return `${accountId}:${idempotencyKey}`;
}

function get(accountId, idempotencyKey) {
  if (!idempotencyKey) return null;
  return cache.get(getCacheKey(accountId, idempotencyKey));
}

function set(accountId, idempotencyKey, response) {
  if (!idempotencyKey) return;
  cache.set(getCacheKey(accountId, idempotencyKey), response);
}

module.exports = { get, set };

