const db = require("./db");

async function ensureTable() {
  try {
    await db.query(
      "CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, account_id INT NOT NULL, response JSONB NOT NULL, created_at TIMESTAMP DEFAULT now())"
    );
  } catch (err) {
    console.error("Failed to create idempotency_keys table:", err);
  }
}

ensureTable();

async function withIdempotency(key, accountId, fn) {
  if (!key) return fn();

  const existing = await db.query(
    "SELECT response FROM idempotency_keys WHERE key = $1 AND account_id = $2",
    [key, accountId]
  );

  if (existing.length > 0) {
    return existing[0].response;
  }

  const result = await fn();

  await db.query(
    "INSERT INTO idempotency_keys (key, account_id, response) VALUES ($1, $2, $3) ON CONFLICT (key) DO NOTHING",
    [key, accountId, JSON.stringify(result)]
  );

  return result;
}

module.exports = { withIdempotency };

